/** Immutable captured blocks. A materialized header describes native owners and never grants another usable inventory. */
public final class NativeGearPayload {
    public record Transform(double xx,double xy,double xz,double yx,double yy,double yz,double zx,double zy,double zz,double tx,double ty,double tz){
        public ListTag write(){var list=new ListTag();for(double value:new double[]{xx,xy,xz,yx,yy,yz,zx,zy,zz,tx,ty,tz})list.add(DoubleTag.valueOf(value));return list;}
        public static Transform read(Tag raw){if(!(raw instanceof ListTag list)||list.size()!=12||list.getElementType()!=Tag.TAG_DOUBLE)throw new IllegalArgumentException("Malformed arm capture reference");double[] values=new double[12];for(int i=0;i<12;i++){values[i]=list.getDouble(i);if(!Double.isFinite(values[i])||Math.abs(values[i])>(i<9?1.000000001:128))throw new IllegalArgumentException("Arm capture reference component bound");}var transform=new Transform(values[0],values[1],values[2],values[3],values[4],values[5],values[6],values[7],values[8],values[9],values[10],values[11]);for(int a=0;a<3;a++)for(int b=0;b<3;b++){double dot=values[a]*values[b]+values[3+a]*values[3+b]+values[6+a]*values[6+b];if(Math.abs(dot-(a==b?1:0))>1e-8)throw new IllegalArgumentException("Nonrigid arm capture reference");}double determinant=values[0]*(values[4]*values[8]-values[5]*values[7])-values[1]*(values[3]*values[8]-values[5]*values[6])+values[2]*(values[3]*values[7]-values[4]*values[6]);if(Math.abs(determinant-1)>1e-8)throw new IllegalArgumentException("Reflected arm capture reference");return transform;}
        public Vec3 point(double x,double y,double z){return new Vec3(xx*x+xy*y+xz*z+tx,yx*x+yy*y+yz*z+ty,zx*x+zy*y+zz*z+tz);}
        public Vec3 vector(double x,double y,double z){return new Vec3(xx*x+xy*y+xz*z,yx*x+yy*y+yz*z,zx*x+zy*y+zz*z);}
        public Transform inverse(){return new Transform(xx,yx,zx,xy,yy,zy,xz,yz,zz,-xx*tx-yx*ty-zx*tz,-xy*tx-yy*ty-zy*tz,-xz*tx-yz*ty-zz*tz);}
        private Transform compose(Transform b){return new Transform(xx*b.xx+xy*b.yx+xz*b.zx,xx*b.xy+xy*b.yy+xz*b.zy,xx*b.xz+xy*b.yz+xz*b.zz,yx*b.xx+yy*b.yx+yz*b.zx,yx*b.xy+yy*b.yy+yz*b.zy,yx*b.xz+yy*b.yz+yz*b.zz,zx*b.xx+zy*b.yx+zz*b.zx,zx*b.xy+zy*b.yy+zz*b.zy,zx*b.xz+zy*b.yz+zz*b.zz,xx*b.tx+xy*b.ty+xz*b.tz+tx,yx*b.tx+yy*b.ty+yz*b.tz+ty,zx*b.tx+zy*b.ty+zz*b.tz+tz);}
    }
    private final List<NativeGearSnapshot.Cell> cells;private final List<List<AABB>> shapes;private final double capturePhase;private final boolean materialized;private final UUID id;private final Transform reference;private NativeGearPayloadView cachedView;private CompoundTag cachedViewTag;private final int bytes;
    NativeGearPayload(UUID id,List<NativeGearSnapshot.Cell> cells,List<List<AABB>> shapes,double phase,boolean materialized,Transform reference){this.reference=reference;this.id=Objects.requireNonNull(id);this.cells=List.copyOf(cells);this.shapes=shapes.stream().map(List::copyOf).toList();if(cells.isEmpty()||cells.size()>8192||cells.size()!=shapes.size()||!Double.isFinite(phase)||phase<0||phase>1)throw new IllegalArgumentException("Arm payload shape/phase bound");int weight=256;Set<BlockPos> seen=new HashSet<>();for(int i=0;i<cells.size();i++){if(!seen.add(cells.get(i).pos)||shapes.get(i).isEmpty()||shapes.get(i).size()>128)throw new IllegalArgumentException("Arm payload cells/shape bound");weight=Math.addExact(weight,cells.get(i).bytes()+64*shapes.get(i).size());}NativeGearBuilderCapture.validate(cells);if(weight>NativeGearSnapshot.MAX_BYTES)throw new IllegalArgumentException("Arm payload byte bound");capturePhase=phase;this.materialized=materialized;bytes=weight;}
    public Transform reference(){return Objects.requireNonNull(reference,"Legacy arm capture frame requires migration");}
    NativeGearPayload migrateLegacy(NativeGearEntity owner){return reference!=null?this:new NativeGearPayload(id,cells,shapes,capturePhase,materialized,legacyFrame(owner,capturePhase));}
    public NativeGearPayloadView view(BlockPos root,HolderLookup.Provider registries){var view=cachedView;if(view==null)cachedView=view=NativeGearPayloadView.from(this,root,registries);return view;}
    CompoundTag viewTag(BlockPos root,HolderLookup.Provider registries){if(cachedViewTag==null)cachedViewTag=view(root,registries).write();return cachedViewTag.copy();}
    public UUID id(){return id;}public int size(){return cells.size();}public int retainedBytes(){return bytes;}public boolean materialized(){return materialized;}public double capturePhase(){return capturePhase;}
    List<NativeGearSnapshot.Cell> cells(){return cells;}
    List<AABB> shapes(int cell){return shapes.get(cell);}
    /** Only captured ownership can be edited; native endpoint blocks remain their own inventory owners. */
    NativeGearPayload withoutCell(int selected){
        if(materialized||selected<0||selected>=cells.size())throw new IllegalArgumentException("Invalid captured payload removal");
        if(cells.size()==1)return null;
        if(NativeGearBuilderCapture.builder(cells.get(selected).state))throw new IllegalArgumentException("Return the builder to a native endpoint before mining");
        var remaining=new ArrayList<>(cells);var collision=new ArrayList<>(shapes);remaining.remove(selected);collision.remove(selected);
        return new NativeGearPayload(id,remaining,collision,capturePhase,false,reference());
    }
    NativeGearPayload withTile(int selected,net.minecraft.nbt.CompoundTag tile){
        if(materialized||selected<0||selected>=cells.size()||tile==null||!cells.get(selected).state.hasBlockEntity())throw new IllegalArgumentException("Invalid captured tile update");
        var before=cells.get(selected);var next=new ArrayList<>(cells);next.set(selected,new NativeGearSnapshot.Cell(before.pos,before.state,tile));
        return new NativeGearPayload(id,next,shapes,capturePhase,false,reference());
    }
    public static Transform frame(NativeGearEntity owner,double phase){
        var raw=frame(owner,owner.pose(phase));if(owner.mode()!=com.vandorlabs.gear.core.GearMotion.Mode.ROTATE||owner.assembly()==null)return raw;
        // Match Source's smooth native-grid endpoint correction using the construction foot's lower corner.
        var rest=frame(owner,owner.pose(1));var corner=NativeGearOrientation.vector(owner.mount(),new BlockPos(0,-owner.assembly().columnHeight(),0));var anchor=rest.inverse().point(corner.getX(),corner.getY(),corner.getZ());double dx=0,dy=0,dz=0;
        if(quarter(owner.settings().activeAngle())){var point=frame(owner,owner.pose(0)).point(anchor.x,anchor.y,anchor.z);double t=1-phase,t2=t*t*(3-2*t);dx+=(Math.rint(point.x)-point.x)*t2;dy+=(Math.rint(point.y)-point.y)*t2;dz+=(Math.rint(point.z)-point.z)*t2;}
        if(quarter(owner.settings().startAngle())){var point=rest.point(anchor.x,anchor.y,anchor.z);double t=phase*phase*(3-2*phase);dx+=(Math.rint(point.x)-point.x)*t;dy+=(Math.rint(point.y)-point.y)*t;dz+=(Math.rint(point.z)-point.z)*t;}
        return new Transform(raw.xx,raw.xy,raw.xz,raw.yx,raw.yy,raw.yz,raw.zx,raw.zy,raw.zz,raw.tx+dx,raw.ty+dy,raw.tz+dz);
    }
    private static boolean quarter(double angle){return Math.abs(angle/90-Math.rint(angle/90))<1e-8;}

    private static Transform legacyFrame(NativeGearEntity owner,double phase){if(owner.definition().kind!=NativeGearDefinition.Kind.EXTENDER||owner.assembly()==null||owner.assembly().kind()!=com.vandorlabs.gear.core.GearTopology.FootKind.NONE)return frame(owner,phase);int height=owner.assembly().columnHeight();double extension=owner.settings().activeExtension()<0?(height==1?-.5:1-height):height;return frame(owner,com.vandorlabs.gear.core.GearMotion.pose(owner.mode(),com.vandorlabs.gear.core.GearMotion.Direction.values()[owner.settings().direction()],height,phase,-height-extension,0,owner.socketOffset(),owner.settings().activeAngle(),owner.settings().startAngle(),owner.settings().middleHinge()));}
    private static Transform frame(NativeGearEntity owner,com.vandorlabs.gear.core.GearMotion.Pose motion){var o=motion.transformFootVertex(0,0,0);var a=motion.transformFootVertex(1,0,0);var b=motion.transformFootVertex(0,1,0);var c=motion.transformFootVertex(0,0,1);var zero=NativeGearOrientation.point(owner.mount(),o.x,o.y,o.z);var x=NativeGearOrientation.vector(owner.mount(),a.x-o.x,a.y-o.y,a.z-o.z);var y=NativeGearOrientation.vector(owner.mount(),b.x-o.x,b.y-o.y,b.z-o.z);var z=NativeGearOrientation.vector(owner.mount(),c.x-o.x,c.y-o.y,c.z-o.z);return new Transform(x.x,y.x,z.x,x.y,y.y,z.y,x.z,y.z,z.z,zero.x,zero.y,zero.z);}
    public Transform transform(NativeGearEntity owner,double phase){return relativeTransform(owner,phase,reference());}
    public static Transform relativeTransform(NativeGearEntity owner,double phase,Transform reference){return frame(owner,phase).compose(reference.inverse());}
    public List<AABB> boxes(NativeGearEntity owner,double phase){if(materialized)return List.of();var transform=transform(owner,phase);var result=new ArrayList<AABB>();var root=owner.getBlockPos();for(int i=0;i<cells.size();i++){var offset=cells.get(i).pos.subtract(root);for(var box:shapes.get(i)){double lx=Double.POSITIVE_INFINITY,ly=lx,lz=lx,hx=Double.NEGATIVE_INFINITY,hy=hx,hz=hx;for(int n=0;n<8;n++){var p=transform.point(offset.getX()+((n&1)==0?box.minX:box.maxX),offset.getY()+((n&2)==0?box.minY:box.maxY),offset.getZ()+((n&4)==0?box.minZ:box.maxZ));lx=Math.min(lx,p.x);ly=Math.min(ly,p.y);lz=Math.min(lz,p.z);hx=Math.max(hx,p.x);hy=Math.max(hy,p.y);hz=Math.max(hz,p.z);}result.add(new AABB(lx+root.getX(),ly+root.getY(),lz+root.getZ(),hx+root.getX(),hy+root.getY(),hz+root.getZ()));}}return List.copyOf(result);}
    private static Direction map(Transform transform,Direction face){var p=transform.vector(face.getStepX(),face.getStepY(),face.getStepZ());var result=Direction.getNearest(p.x,p.y,p.z);if(p.distanceToSqr(Vec3.atLowerCornerOf(result.getNormal()))>1e-12)throw new IllegalArgumentException("Arm endpoint is not grid aligned");return result;}
    @SuppressWarnings({"rawtypes","unchecked"}) private static BlockState rotate(BlockState state,Transform transform,boolean tile){var next=state;boolean changed=false;for(var property:state.getProperties())if(property instanceof DirectionProperty direction){var before=state.getValue(direction);var after=map(transform,before);if(!direction.getPossibleValues().contains(after))throw new IllegalArgumentException("Attachment facing cannot be materialized at this angle");next=next.setValue(direction,after);changed|=after!=before;}else if(property instanceof EnumProperty axis&&axis.getValueClass()==Direction.Axis.class){Direction.Axis before=(Direction.Axis)state.getValue(axis);Direction.Axis after=map(transform,before==Direction.Axis.X?Direction.EAST:before==Direction.Axis.Y?Direction.UP:Direction.SOUTH).getAxis();next=next.setValue(axis,after);changed|=after!=before;}else if(property.getName().equals("half")||property.getName().equals("type")||property.getName().equals("rotation")||property.getName().equals("shape")){if(map(transform,Direction.UP)!=Direction.UP||map(transform,Direction.NORTH)!=Direction.NORTH)throw new IllegalArgumentException("This shaped attachment needs a supported native endpoint orientation");}if(tile&&changed&&!(state.getBlock() instanceof com.vandorlabs.neoforge.appliances.NativeApplianceBlock)&&!(state.getBlock() instanceof com.vandorlabs.neoforge.navigation.NativeNavigationTableBlock)&&!(state.getBlock() instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverCoreBlock)&&!(state.getBlock() instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverPartBlock))throw new IllegalArgumentException("This attachment tile needs a supported native orientation adapter");return next;}
    List<NativeGearSnapshot.Cell> endpoint(NativeGearEntity owner,double phase){var transform=transform(owner,phase);for(Direction face:Direction.values())map(transform,face);if(!NativeGearBuilderCapture.nativeOrientation(owner,this,transform))return List.of();var result=new ArrayList<NativeGearSnapshot.Cell>();var root=owner.getBlockPos();Set<BlockPos> seen=new HashSet<>();for(var cell:cells){if((cell.state.getBlock() instanceof com.vandorlabs.neoforge.navigation.NativeNavigationTableBlock||cell.state.getBlock() instanceof com.vandorlabs.neoforge.appliances.NativeApplianceBlock)&&map(transform,Direction.UP)!=Direction.UP)return List.of();if(cell.state.getBlock() instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverCoreBlock&&Math.abs(transform.vector(0,1,0).y)<1-1e-8)return List.of();if(cell.state.getBlock() instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverCoreBlock||cell.state.getBlock() instanceof com.vandorlabs.neoforge.navigation.NativeNavigationTableBlock||cell.state.getBlock() instanceof com.vandorlabs.neoforge.appliances.NativeApplianceBlock)for(var property:cell.state.getProperties())if(property instanceof DirectionProperty direction&&!direction.getPossibleValues().contains(map(transform,cell.state.getValue(direction))))return List.of();var local=cell.pos.subtract(root);var center=transform.point(local.getX()+.5,local.getY()+.5,local.getZ()+.5);if(Math.abs(center.x-.5-Math.rint(center.x-.5))+Math.abs(center.y-.5-Math.rint(center.y-.5))+Math.abs(center.z-.5-Math.rint(center.z-.5))>1e-8)return List.of();var target=root.offset((int)Math.rint(center.x-.5),(int)Math.rint(center.y-.5),(int)Math.rint(center.z-.5));if(!seen.add(target))throw new IllegalArgumentException("Arm endpoint overlaps itself");var next=cell.at(target,rotate(cell.state,transform,cell.tile()!=null));var tag=next.tile();if(tag!=null){if(cell.state.getBlock() instanceof com.vandorlabs.neoforge.navigation.NativeNavigationTableBlock)com.vandorlabs.neoforge.navigation.NativeNavigationTableEntity.rotateTag(tag,transform);else if(cell.state.getBlock() instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverCoreBlock||cell.state.getBlock() instanceof com.vandorlabs.neoforge.navigation.observer.NativeObserverPartBlock)com.vandorlabs.neoforge.navigation.observer.NativeObserverRotation.rotateTag(tag,transform,cell.state);next=new NativeGearSnapshot.Cell(target,next.state,tag,next.section);}result.add(next);}NativeGearBuilderCapture.validate(result);return List.copyOf(result);}
    NativeGearPayload materialized(NativeGearEntity owner,double phase,List<NativeGearSnapshot.Cell> endpoint){return new NativeGearPayload(id,endpoint,shapes,phase,true,frame(owner,phase));}
    public CompoundTag write(){var tag=new CompoundTag();tag.putInt("Schema",2);tag.put("Reference",reference().write());tag.putUUID("Identity",id);tag.putDouble("CapturePhase",capturePhase);tag.putBoolean("Materialized",materialized);var list=new ListTag();for(int i=0;i<cells.size();i++){var cell=cells.get(i).write();var boxes=new ListTag();for(var box:shapes.get(i)){var entry=new ListTag();for(double value:new double[]{box.minX,box.minY,box.minZ,box.maxX,box.maxY,box.maxZ})entry.add(DoubleTag.valueOf(value));boxes.add(entry);}cell.put("Boxes",boxes);list.add(cell);}tag.put("Cells",list);return tag;}
    static NativeGearPayload read(HolderLookup.Provider registries,BlockPos root,CompoundTag tag){if(tag.sizeInBytes()>NativeGearSnapshot.MAX_BYTES||!tag.getAllKeys().equals(tag.getInt("Schema")==1?Set.of("Schema","Identity","CapturePhase","Materialized","Cells"):Set.of("Schema","Identity","CapturePhase","Materialized","Cells","Reference"))||!tag.contains("Schema",Tag.TAG_INT)||!Set.of(1,2).contains(tag.getInt("Schema"))||!tag.hasUUID("Identity")||!tag.contains("CapturePhase",Tag.TAG_DOUBLE)||!tag.contains("Materialized",Tag.TAG_BYTE)||!(tag.get("Cells") instanceof ListTag list)||list.isEmpty()||list.size()>8192||list.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Malformed arm payload envelope");var cells=new ArrayList<NativeGearSnapshot.Cell>();var shapes=new ArrayList<List<AABB>>();for(var raw:list){var entry=((CompoundTag)raw).copy();if(!(entry.get("Boxes") instanceof ListTag boxes)||boxes.isEmpty()||boxes.size()>128||boxes.getElementType()!=Tag.TAG_LIST)throw new IllegalArgumentException("Malformed arm payload collision");var parsed=new ArrayList<AABB>();for(var value:boxes){var coordinates=(ListTag)value;if(coordinates.size()!=6||coordinates.getElementType()!=Tag.TAG_DOUBLE)throw new IllegalArgumentException("Malformed arm payload cuboid");double[] c=new double[6];for(int i=0;i<6;i++){c[i]=coordinates.getDouble(i);if(!Double.isFinite(c[i])||c[i]<-1||c[i]>2)throw new IllegalArgumentException("Arm payload collision coordinate bound");}if(c[0]>=c[3]||c[1]>=c[4]||c[2]>=c[5])throw new IllegalArgumentException("Empty arm payload cuboid");parsed.add(new AABB(c[0],c[1],c[2],c[3],c[4],c[5]));}entry.remove("Boxes");var cell=NativeGearSnapshot.read(registries,entry,root);if(cell.section||cell.state.isAir())throw new IllegalArgumentException("Empty owned arm payload cell");NativeGearSnapshot.stage(registries,cell,false);cells.add(cell);shapes.add(parsed);}return new NativeGearPayload(tag.getUUID("Identity"),cells,shapes,tag.getDouble("CapturePhase"),tag.getBoolean("Materialized"),tag.getInt("Schema")==1?null:Transform.read(tag.get("Reference")));}
}
